package com.kazurayam.wgetlog;

import java.io.Reader;
import java.util.Iterator;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class Digester implements Iterator<WgetLogEntry> {
    private static final Logger logger = LoggerFactory.getLogger(Digester.class);

    private final RewindableLineReader rlr;
    WgetLogEntry nextEntry = null;

    Digester(Reader reader) {
        rlr = new RewindableLineReader(reader);
        nextEntry = digest(rlr);
    }

    public WgetLogEntry next() {
        WgetLogEntry buffer = nextEntry;
        nextEntry = digest(rlr);
        return buffer;
    }

    public boolean hasNext() {
        return nextEntry != null;
    }

    private WgetLogEntry digest(RewindableLineReader rlr) {
        StringBuilder sb = new StringBuilder();
        String line;
        while((line = rlr.getLine()) != null) {
            if (line.startsWith("--")) {
                if (sb.isEmpty()) {
                    sb.append(line);
                } else {
                    rlr.ungetLine(line);
                    break;
                }
            } else {
                sb.append(line);
            }
        }
        if (!sb.isEmpty()) {
            return new WgetLogEntry(sb.toString());
        } else {
            return null;
        }
    }
}
